CREATE OR REPLACE FUNCTION public.decide_property_sale_offer(_offer_id uuid, _decision text) RETURNS public.property_sale_offers LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.property_sale_offers; minimum numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autentificarea este obligatorie'; END IF; IF _decision NOT IN ('acceptata','respinsa') THEN RAISE EXCEPTION 'Decizie invalidă'; END IF; SELECT * INTO o FROM public.property_sale_offers WHERE id=_offer_id FOR UPDATE; IF NOT FOUND OR NOT public.is_property_owner(o.property_id) THEN RAISE EXCEPTION 'Nu aveți acces la această ofertă'; END IF; IF o.status <> 'primita' THEN RAISE EXCEPTION 'Oferta nu mai este disponibilă pentru o decizie'; END IF; SELECT min_price_eur INTO minimum FROM public.property_sale_settings WHERE property_id=o.property_id; IF _decision='acceptata' AND minimum IS NOT NULL AND o.amount_eur<minimum THEN RAISE EXCEPTION 'Oferta este sub prețul minim salvat'; END IF; UPDATE public.property_sale_offers SET status=_decision,updated_at=now() WHERE id=_offer_id RETURNING * INTO o; RETURN o; END $$; REVOKE ALL ON FUNCTION public.decide_property_sale_offer(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_property_sale_offer(uuid,text) TO authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON public.property_sale_offers TO authenticated; GRANT ALL ON public.property_sale_offers TO service_role; CREATE OR REPLACE FUNCTION public.validate_property_sale_offer() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.amount_eur IS NULL OR NEW.amount_eur<=0 OR NEW.amount_eur>100000000 THEN RAISE EXCEPTION 'Suma ofertei este invalidă'; END IF; IF length(trim(coalesce(NEW.buyer_label,'')))<2 OR length(NEW.buyer_label)>150 THEN RAISE EXCEPTION 'Eticheta cumpărătorului este invalidă'; END IF; IF length(coalesce(NEW.conditions,''))>2000 OR length(coalesce(NEW.payment_method,''))>150 THEN RAISE EXCEPTION 'Detaliile ofertei sunt prea lungi'; END IF; NEW.updated_at=now(); RETURN NEW; END $$; CREATE TRIGGER validate_property_sale_offer_before_write BEFORE INSERT OR UPDATE ON public.property_sale_offers FOR EACH ROW EXECUTE FUNCTION public.validate_property_sale_offer();